const rows=$input.all().map(item=>item.json);
const config=$('Digest Configuration').first().json;
const zone='America/Los_Angeles';
const ymd=d=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const today=ymd(new Date());
const dateValue=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?null:d;};
const filtered=rows.filter(j=>{const d=dateValue(j['First Seen At']);return d&&ymd(d)===today&&String(j.Link||'').trim()});
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const getUrl=j=>String(config.dashboardUrl||'').replace(/\/$/,'')+'?job='+encodeURIComponent(String(j.Link).trim());
const cleanText=s=>String(s??'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const description=s=>{const v=cleanText(s);return v.length>170?v.slice(0,167)+'…':v};
const score=j=>{const n=Number(String(j.Rating??'').trim());return Number.isFinite(n)?n:null;};
const sorted=filtered.sort((a,b)=>(score(b)??-1)-(score(a)??-1));
const isHigh=j=>score(j)>85;
const countHigh=sorted.filter(isHigh).length;

const lines=sorted.map(j=>'<tr><td style="padding:9px;border:1px solid #ddd">'+esc(j.Title||'Untitled')+'</td><td style="padding:9px;border:1px solid #ddd">'+esc(description(j['Job Description']))+'</td><td style="padding:9px;border:1px solid #ddd">'+esc(j.Type||'Not specified')+'</td><td style="padding:9px;border:1px solid #ddd">'+(score(j)??'Pending')+'</td><td style="padding:9px;border:1px solid #ddd"><a href="'+esc(getUrl(j))+'">View in dashboard</a></td></tr>').join('');
const table=sorted.length?'<table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px"><thead><tr style="background:#eef2f6"><th style="padding:9px;border:1px solid #ddd">Job title</th><th style="padding:9px;border:1px solid #ddd">Description</th><th style="padding:9px;border:1px solid #ddd">Job type</th><th style="padding:9px;border:1px solid #ddd">Rating</th><th style="padding:9px;border:1px solid #ddd">Dashboard</th></tr></thead><tbody>'+lines+'</tbody></table>':'<p>No new jobs were discovered today.</p>';
const html='<div style="font-family:Arial,sans-serif;color:#223344"><p>Hello,</p><p>Here is your daily job summary for '+esc(today)+'.</p><p><strong>'+sorted.length+' new jobs</strong> · '+countHigh+' rated over 85</p>'+table+'<p>These records were first discovered today. Ratings reflect the latest values in Google Sheets.</p></div>';
return [{json:{emailSubject:'Daily job summary — '+today+' ('+sorted.length+' new)',emailHtml:html,newJobs:sorted.length,highRated:countHigh}}];

const rows=$input.all().map(item=>item.json);
const config=$('Digest Configuration').first().json;
const zone='America/Los_Angeles';
const ymd=d=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const today=ymd(new Date());
const dateValue=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?null:d;};
const filtered=rows.filter(j=>{const d=dateValue(j['First Seen At']);return d&&ymd(d)===today&&String(j.Link||'').trim()});
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const getUrl=j=>String(config.dashboardUrl||'').replace(/\/$/,'')+'?job='+encodeURIComponent(String(j.Link).trim());
const cleanText=s=>String(s??'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const description=s=>{const v=cleanText(s);return v.length>170?v.slice(0,167)+'…':v};
const score=j=>{const n=Number(String(j.Rating??'').trim());return Number.isFinite(n)?n:null;};
const sorted=filtered.sort((a,b)=>(score(b)??-1)-(score(a)??-1));
const isHigh=j=>score(j)>85;
const countHigh=sorted.filter(isHigh).length;

const intro='🌙 Daily job digest — '+today+'\nNew jobs: '+sorted.length+' | Scored 86+: '+countHigh+'\n\n';
const chunks=[];
let current=intro;
for(const j of sorted){
 const entry=String(j.Title||'Untitled')+'\n'+String(j['Company Name']||'Unknown company')+' | '+String(j.Type||'Not specified')+'\nRating: '+(score(j)??'Pending')+'/100\n'+description(j['Job Description'])+'\nDashboard: '+getUrl(j)+'\n\n';
 if(current.length+entry.length>3400&&current!==intro){chunks.push(current);current='🌙 Daily digest (continued)\n\n';}
 current+=entry;
}
if(!sorted.length)current+='No new jobs were discovered today.';
chunks.push(current);
return chunks.map((telegramText,i)=>({json:{telegramText,chunk:i+1,totalChunks:chunks.length}}));
